declare(strict_types=1);require dirname(__DIR__).'/private/site.php';require dirname(__DIR__).'/private/site-view.php';security_headers();
$slug=$_GET['case']??'';$p=false;try{if(is_string($slug)&&preg_match('/^[a-z][a-z0-9-]{2,79}$/D',$slug))$p=query("SELECT * FROM nd_publications WHERE slug=? AND kind='portfolio' AND state='PUBLISHED'",[$slug])->fetch();if($p&&!site_live($p))$p=false;}catch(Throwable $e){http_response_code(503);site_header('Портфолио');echo '<main class="wrap site-main"><h1>Портфолио временно недоступно.</h1><a href="/portfolio.php">Вернуться к работам</a></main>';site_footer();exit;}
if(!$p){http_response_code(404);site_header('Работа не найдена');echo '<main class="wrap site-main"><h1>Работа не найдена.</h1><a href="/portfolio.php">Все работы</a></main>';site_footer();exit;}$b=site_version((int)$p['published_version_id']);site_header($b['title']);?>
<main class="wrap site-main"><a href="/portfolio.php">← Все работы</a><h1><?= esc($b['title']) ?></h1><p class="guide-intro"><?= esc($b['short_description']??'') ?></p>
<?php foreach(['task'=>'Задача','work'=>'Что сделано','result'=>'Результат','text'=>'О проекте'] as $key=>$label):if(empty($b[$key]))continue; ?><section><h2><?= $label ?></h2><p class="case-text"><?= esc($b[$key]) ?></p></section><?php endforeach; ?>
<?php if(!empty($b['project_url'])): ?><p><a href="<?= esc($b['project_url']) ?>" target="_blank" rel="noopener noreferrer">Открыть проект ↗</a></p><?php endif; ?>
<section class="publication-grid case-gallery" aria-label="Материалы проекта"><?php foreach($b['media']??[] as $m): ?><figure><?php if(isset($m['external_url'])): ?><a href="<?= esc($m['external_url']) ?>" target="_blank" rel="noopener noreferrer">Открыть видео ↗</a><?php elseif(str_starts_with($m['mime'],'image/')): ?><a href="/portfolio-api.php?r=media&amp;id=<?= (int)$m['id'] ?>" target="_blank" rel="noopener"><img src="/portfolio-api.php?r=media&amp;id=<?= (int)$m['id'] ?>" alt="<?= esc($m['caption']??'') ?>" loading="lazy"></a><?php else: ?><video controls preload="metadata" src="/portfolio-api.php?r=media&amp;id=<?= (int)$m['id'] ?>"></video><?php endif; ?><figcaption><?= esc($m['caption']??'') ?></figcaption></figure><?php endforeach; ?></section>
